    for(auto handle:travelers){if(!active())return;if(!alive(handle,NativeKind::Unit))continue;auto u=units_.at(handle);if(u->owner!=cast.owner || u->removing || u->hidden() || u->paused || u->rooted() || number(u->life)<=0)continue;auto desired=destination;if(!s.teleportCluster)desired=requireWorld().clamp({real(number(destination.x)+number(u->x)-number(origin.x)),real(number(destination.y)+number(u->y)-number(origin.y))});auto at=placement.find(*u,desired);if(!at){if(handle==id)break;continue;}spellVisual(s,"Specialart",0,{u->x,u->y});placement.remove(*u);u->x=at->x;u->y=at->y;u->route.clear();u->waypoint=0;u->holding=false;u->combat.home=*at;u->animation.clear();u->animationTime=0;++u->animationGeneration;if(handle!=id)u->currentOrder=0;unitFootprint(*u);placement.add(*u);spellVisual(s,"Specialart",handle,*at);++fogRevision_;}
